import{_ as t,a,o as n,a4 as i}from"./chunks/framework.-FZumj2l.js";const p=JSON.parse('{"title":"Events","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/marketing/communications/events/index.md","filePath":"api/graphql-api/admin/marketing/communications/events/index.md","lastUpdated":1783327468000}'),o={name:"api/graphql-api/admin/marketing/communications/events/index.md"};function r(s,e,d,m,h,c){return n(),a("div",null,e[0]||(e[0]=[i('<h1 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h1><p>A <strong>marketing event</strong> is a dated milestone — such as a sale kickoff or a holiday — that anchors when campaigns go out. It mirrors the admin <strong>Marketing → Communications → Events</strong> screen.</p><h2 id="how-an-event-works" tabindex="-1">How an event works <a class="header-anchor" href="#how-an-event-works" aria-label="Permalink to &quot;How an event works&quot;">​</a></h2><p>An event is intentionally lightweight: a name, a description, and a single date.</p><ul><li><strong><code>name</code></strong> — a short label for the event (e.g. <em>Holiday Sale Kickoff</em>).</li><li><strong><code>description</code></strong> — free-text notes about what the event is for.</li><li><strong><code>date</code></strong> — the event date in <code>YYYY-MM-DD</code> form. This is the day the event is anchored to.</li></ul><p><strong>What an event is used for.</strong> A campaign can reference an event so that a scheduled send lines up with the event&#39;s date — the event provides the calendar anchor while the campaign provides the email template and audience.</p><p><strong>No mass delete.</strong> Events are managed one at a time; the admin screen offers no bulk-delete action, so neither does the API.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/marketing/communications/events-list.html">List</a></td><td><code>adminMarketingEvents</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/communications/events-detail.html">Detail</a></td><td><code>adminMarketingEvent</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/communications/events-create.html">Create</a></td><td><code>createAdminMarketingEvent</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/communications/events-update.html">Update</a></td><td><code>updateAdminMarketingEvent</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/communications/events-delete.html">Delete</a></td><td><code>deleteAdminMarketingEvent</code> mutation</td></tr></tbody></table><p><strong>Relation.</strong> Events pair with <a href="/api/graphql-api/admin/marketing/communications/campaigns/">Campaigns</a> — a campaign may reference an event so its send lines up with the event date.</p><p>All Events operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',11)]))}const g=t(o,[["render",r]]);export{p as __pageData,g as default};
